\mathcal S^T\coloneqq\left\{\begin{gathered}
\frac{}{\mathsf T(\Xi,\Gamma,v_i,\gamma_i)}\ (i\in[m]),\qquad
\frac{}{\mathsf T(\Xi,\Gamma,\star,1)},\\
\frac{\mathsf T(\Xi,\Gamma,t,\sigma)\quad\mathsf T(\Xi,\Gamma,u,\tau)}
{\mathsf T(\Xi,\Gamma,\langle t,u\rangle,\sigma\times\tau)},\qquad
\frac{\mathsf T(\Xi,\Gamma,t,\sigma_1\times\sigma_2)}{\mathsf T(\Xi,\Gamma,\pi_i t,\sigma_i)}\ (i\in\{1,2\}),\\
\frac{\mathsf T(\Xi,\Gamma,x:\sigma;t,\tau)}{\mathsf T(\Xi,\Gamma,\lambda(\sigma,t),\sigma\to\tau)}
\ (x\in V\setminus\operatorname{dom}\Gamma),\\
\frac{\mathsf T(\Xi,\Gamma,f,\sigma\to\tau)\quad\mathsf T(\Xi,\Gamma,t,\sigma)}
{\mathsf T(\Xi,\Gamma,\mathrm{app}(f,t),\tau)},\\
\frac{\mathsf T(\Xi,\alpha;W^\alpha\Gamma,t,\sigma)}
{\mathsf T(\Xi,\Gamma,\Lambda t,\forall\sigma)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi),\\
\frac{\mathsf T(\Xi,\Gamma,t,\forall\sigma)\quad\mathsf F(\Xi,\tau)}
{\mathsf T(\Xi,\Gamma,\mathrm{tapp}(t,\tau),\sigma\langle\tau\rangle)},\\
\frac{\mathsf F(\Xi,\alpha;\sigma)\quad\mathsf F(\Xi,\tau)\quad\mathsf T(\Xi,\Gamma,t,\sigma\langle\tau\rangle)}
{\mathsf T(\Xi,\Gamma,\mathrm{pack}(\sigma,\tau,t),\exists\sigma)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi),\\
\frac{\mathsf T(\Xi,\Gamma,t,\exists\sigma)\quad
\mathsf T(\Xi,\alpha;W^\alpha\Gamma,x:\sigma;u,W^\alpha\rho)\quad\mathsf F(\Xi,\rho)}
{\mathsf T(\Xi,\Gamma,\mathrm{unpack}(t,u),\rho)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi,\ x\in V\setminus\operatorname{dom}\Gamma).
\end{gathered}\right\}.

\mathcal S^E\coloneqq\left\{\begin{gathered}
\frac{\mathsf T(\Xi,\Gamma,t,\sigma)}{\mathsf E(\Xi,\Gamma,t,t,\sigma)},\qquad
\frac{\mathsf E(\Xi,\Gamma,t,u,\sigma)}{\mathsf E(\Xi,\Gamma,u,t,\sigma)},\\
\frac{\mathsf E(\Xi,\Gamma,t,u,\sigma)\quad\mathsf E(\Xi,\Gamma,u,w,\sigma)}
{\mathsf E(\Xi,\Gamma,t,w,\sigma)},\\
\frac{\mathsf E(\Xi,\Gamma,t,t',\sigma)\quad\mathsf E(\Xi,\Gamma,u,u',\tau)}
{\mathsf E(\Xi,\Gamma,\langle t,u\rangle,\langle t',u'\rangle,\sigma\times\tau)},\\
\frac{\mathsf E(\Xi,\Gamma,t,u,\sigma_1\times\sigma_2)}
{\mathsf E(\Xi,\Gamma,\pi_i t,\pi_i u,\sigma_i)}\ (i\in\{1,2\}),\\
\frac{\mathsf E(\Xi,\Gamma,x:\sigma;t,u,\tau)}
{\mathsf E(\Xi,\Gamma,\lambda(\sigma,t),\lambda(\sigma,u),\sigma\to\tau)}
\ (x\in V\setminus\operatorname{dom}\Gamma),\\
\frac{\mathsf E(\Xi,\Gamma,f,g,\sigma\to\tau)\quad\mathsf E(\Xi,\Gamma,t,u,\sigma)}
{\mathsf E(\Xi,\Gamma,\mathrm{app}(f,t),\mathrm{app}(g,u),\tau)},\\
\frac{\mathsf E(\Xi,\alpha;W^\alpha\Gamma,t,u,\sigma)}
{\mathsf E(\Xi,\Gamma,\Lambda t,\Lambda u,\forall\sigma)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi),\\
\frac{\mathsf E(\Xi,\Gamma,t,u,\forall\sigma)\quad\mathsf F(\Xi,\tau)}
{\mathsf E(\Xi,\Gamma,\mathrm{tapp}(t,\tau),\mathrm{tapp}(u,\tau),\sigma\langle\tau\rangle)},\\
\frac{\mathsf E(\Xi,\Gamma,t,u,\sigma\langle\tau\rangle)\quad\mathsf F(\Xi,\alpha;\sigma)\quad\mathsf F(\Xi,\tau)}
{\mathsf E(\Xi,\Gamma,\mathrm{pack}(\sigma,\tau,t),\mathrm{pack}(\sigma,\tau,u),\exists\sigma)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi),\\
\frac{\mathsf E(\Xi,\Gamma,t,t',\exists\sigma)\quad
\mathsf E(\Xi,\alpha;W^\alpha\Gamma,x:\sigma;u,u',W^\alpha\rho)\quad\mathsf F(\Xi,\rho)}
{\mathsf E(\Xi,\Gamma,\mathrm{unpack}(t,u),\mathrm{unpack}(t',u'),\rho)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi,\ x\in V\setminus\operatorname{dom}\Gamma).
\end{gathered}\right\}.

\mathcal S^{\beta\eta}\coloneqq\left\{\begin{gathered}
\frac{\mathsf T(\Xi,\Gamma,x:\sigma;t,\tau)\quad\mathsf T(\Xi,\Gamma,u,\sigma)}
{\mathsf E(\Xi,\Gamma,\mathrm{app}(\lambda(\sigma,t),u),t\langle u\rangle_x,\tau)}
\ (x\in V\setminus\operatorname{dom}\Gamma),\\
\frac{\mathsf T(\Xi,\Gamma,f,\sigma\to\tau)}
{\mathsf E(\Xi,\Gamma,\lambda(\sigma,\mathrm{app}(W^x f,v_{m+1})),f,\sigma\to\tau)},\\
\frac{\mathsf T(\Xi,\Gamma,t_1,\sigma_1)\quad\mathsf T(\Xi,\Gamma,t_2,\sigma_2)}
{\mathsf E(\Xi,\Gamma,\pi_i\langle t_1,t_2\rangle,t_i,\sigma_i)}\ (i\in\{1,2\}),\\
\frac{\mathsf T(\Xi,\Gamma,t,\sigma\times\tau)}
{\mathsf E(\Xi,\Gamma,\langle\pi_1t,\pi_2t\rangle,t,\sigma\times\tau)},\qquad
\frac{\mathsf T(\Xi,\Gamma,t,1)}{\mathsf E(\Xi,\Gamma,t,\star,1)},\\
\frac{\mathsf T(\Xi,\alpha;W^\alpha\Gamma,t,\sigma)\quad\mathsf F(\Xi,\tau)}
{\mathsf E(\Xi,\Gamma,\mathrm{tapp}(\Lambda t,\tau),t\langle\tau\rangle_\alpha,\sigma\langle\tau\rangle)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi),\\
\frac{\mathsf T(\Xi,\Gamma,f,\forall\sigma)}
{\mathsf E(\Xi,\Gamma,\Lambda(\mathrm{tapp}(W^\alpha f,a_{n+1})),f,\forall\sigma)},\\
\frac{\mathsf F(\Xi,\tau)\quad\mathsf T(\Xi,\Gamma,t,\sigma\langle\tau\rangle)\quad
\mathsf T(\Xi,\alpha;W^\alpha\Gamma,x:\sigma;u,W^\alpha\rho)\quad\mathsf F(\Xi,\rho)}
{\mathsf E(\Xi,\Gamma,\mathrm{unpack}(\mathrm{pack}(\sigma,\tau,t),u),
u\langle\tau,t\rangle_{\alpha,x},\rho)}
\ (\alpha\in A\setminus\operatorname{rng}\Xi,\ x\in V\setminus\operatorname{dom}\Gamma),\\
\frac{\mathsf T(\Xi,\Gamma,t,\exists\sigma)\quad\mathsf T(\Xi,\Gamma,z:\exists\sigma;u,\rho)}
{\mathsf E(\Xi,\Gamma,\mathrm{unpack}(t,\operatorname{open}_\sigma(u)),u\langle t\rangle_x,\rho)}
\ (z\in V\setminus\operatorname{dom}\Gamma).
\end{gathered}\right\}.

\mathcal S^{\rm sub}\coloneqq\left\{\begin{gathered}
\frac{\mathsf F(\Xi,\sigma)\quad(\mathsf F(\Psi,\tau_i))_{i=1}^n}
{\mathsf F(\Psi,\sigma[\boldsymbol\tau])},\\
\frac{\mathsf T(\Xi,\Gamma,t,\sigma)\quad(\mathsf F(\Psi,\tau_i))_{i=1}^n
\quad(\mathsf T(\Psi,\Delta,s_j,\gamma_j[\boldsymbol\tau]))_{j=1}^m}
{\mathsf T(\Psi,\Delta,\mathsf S_{n,m}^{k,\ell}(t;\boldsymbol\tau,\mathbf s),\sigma[\boldsymbol\tau])},\\
\frac{\mathsf E(\Xi,\Gamma,t,u,\sigma)\quad(\mathsf F(\Psi,\tau_i))_{i=1}^n
\quad(\mathsf E(\Psi,\Delta,s_j,r_j,\gamma_j[\boldsymbol\tau]))_{j=1}^m}
{\mathsf E(\Psi,\Delta,\mathsf S_{n,m}^{k,\ell}(t;\boldsymbol\tau,\mathbf s),
\mathsf S_{n,m}^{k,\ell}(u;\boldsymbol\tau,\mathbf r),\sigma[\boldsymbol\tau])}.
\end{gathered}\right\}.
